CREATE TYPE "BodyZone" AS ENUM ('HEAD', 'TORSO', 'LEGS', 'FEET', 'ACCESSORY');
CREATE TYPE "GarmentStatus" AS ENUM ('OWNED', 'WISHLIST');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"userId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Media" ("id" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"path" TEXT NOT NULL,"mime" TEXT NOT NULL,"width" INTEGER,"height" INTEGER,"size" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Media_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Pose" ("id" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"originalMediaId" TEXT NOT NULL,"normalizedMediaId" TEXT NOT NULL,"x" DOUBLE PRECISION NOT NULL DEFAULT 0,"y" DOUBLE PRECISION NOT NULL DEFAULT 0,"scale" DOUBLE PRECISION NOT NULL DEFAULT 1,"rotation" DOUBLE PRECISION NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Pose_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Garment" ("id" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"brand" TEXT,"notes" TEXT,"zone" "BodyZone" NOT NULL,"subtype" TEXT NOT NULL,"status" "GarmentStatus" NOT NULL DEFAULT 'OWNED',"tags" TEXT[] DEFAULT ARRAY[]::TEXT[],"originalMediaId" TEXT NOT NULL,"processedMediaId" TEXT NOT NULL,"thumbnailMediaId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Garment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "GarmentPosePlacement" ("id" TEXT NOT NULL,"garmentId" TEXT NOT NULL,"poseId" TEXT NOT NULL,"x" DOUBLE PRECISION NOT NULL,"y" DOUBLE PRECISION NOT NULL,"scaleX" DOUBLE PRECISION NOT NULL,"scaleY" DOUBLE PRECISION NOT NULL,"rotation" DOUBLE PRECISION NOT NULL DEFAULT 0,"opacity" DOUBLE PRECISION NOT NULL DEFAULT 1,"layer" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "GarmentPosePlacement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Outfit" ("id" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"name" TEXT NOT NULL,"notes" TEXT,"poseId" TEXT NOT NULL,"previewMediaId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Outfit_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OutfitItem" ("id" TEXT NOT NULL,"outfitId" TEXT NOT NULL,"garmentId" TEXT NOT NULL,"zone" "BodyZone" NOT NULL,"layerOrder" INTEGER NOT NULL,"x" DOUBLE PRECISION NOT NULL,"y" DOUBLE PRECISION NOT NULL,"scaleX" DOUBLE PRECISION NOT NULL,"scaleY" DOUBLE PRECISION NOT NULL,"rotation" DOUBLE PRECISION NOT NULL DEFAULT 0,"opacity" DOUBLE PRECISION NOT NULL DEFAULT 1,CONSTRAINT "OutfitItem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash");
CREATE UNIQUE INDEX "Media_path_key" ON "Media"("path");
CREATE UNIQUE INDEX "GarmentPosePlacement_garmentId_poseId_key" ON "GarmentPosePlacement"("garmentId", "poseId");
CREATE INDEX "OutfitItem_outfitId_layerOrder_idx" ON "OutfitItem"("outfitId", "layerOrder");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
