ALTER TABLE "Garment" ADD CONSTRAINT "Garment_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Garment" ADD CONSTRAINT "Garment_originalMediaId_fkey" FOREIGN KEY ("originalMediaId") REFERENCES "Media"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Garment" ADD CONSTRAINT "Garment_processedMediaId_fkey" FOREIGN KEY ("processedMediaId") REFERENCES "Media"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Garment" ADD CONSTRAINT "Garment_thumbnailMediaId_fkey" FOREIGN KEY ("thumbnailMediaId") REFERENCES "Media"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "GarmentPosePlacement" ADD CONSTRAINT "GarmentPosePlacement_garmentId_fkey" FOREIGN KEY ("garmentId") REFERENCES "Garment"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "GarmentPosePlacement" ADD CONSTRAINT "GarmentPosePlacement_poseId_fkey" FOREIGN KEY ("poseId") REFERENCES "Pose"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Outfit" ADD CONSTRAINT "Outfit_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Outfit" ADD CONSTRAINT "Outfit_poseId_fkey" FOREIGN KEY ("poseId") REFERENCES "Pose"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Outfit" ADD CONSTRAINT "Outfit_previewMediaId_fkey" FOREIGN KEY ("previewMediaId") REFERENCES "Media"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "OutfitItem" ADD CONSTRAINT "OutfitItem_outfitId_fkey" FOREIGN KEY ("outfitId") REFERENCES "Outfit"("id") ON DELETE CASCADE ON UPDATE CASCADE;
